    public function run()
    {
        $h5pCPLibParams = ['name' => "H5P.CoursePresentation", "major_version" => 1, "minor_version" => 27];
        $h5pCPLib = DB::table('h5p_libraries')->where($h5pCPLibParams)->first();

        if (empty($h5pCPLib)) {
            $h5pCPLibId = DB::table('h5p_libraries')->insertGetId([
                'name' => 'H5P.CoursePresentation',
                'title' => 'Course Presentation',
                'major_version' => 1,
                'minor_version' => 27,
                'patch_version' => 15,
                'embed_types' => 'iframe',
                'runnable' => 1,
                'restricted' => 0,
                'fullscreen' => 1,
                'preloaded_js' => 'dist/h5p-course-presentation.js',
                'preloaded_css' => 'dist/h5p-course-presentation.css',
                'drop_library_css' => '',
                'semantics' => $this->getSemantics(),
                'tutorial_url' => ' ',
                'has_icon' => 1
            ]);

            $this->insertDependentLibraries($h5pCPLibId);
            $this->insertLibrariesLanguages($h5pCPLibId);

            $organizations = DB::table('organizations')->pluck('id');
            $currentDate = now();

            foreach ($organizations as $organizationId) {
                $activityTypes = DB::table('activity_types')->whereOrganizationId($organizationId)->pluck('id', 'title');
                if (!isset($activityTypes['Presentation'])) {
                    continue;
                }
                $params = ['title' => 'Course Presentation', 'organization_id' => $organizationId];
                DB::table('activity_items')->updateOrInsert($params, [
                    'title' => 'Course Presentation',
                    'image' => '',
                    'description' => 'Create a presentation with interactive slides',
                    'activity_type_id' => $activityTypes['Presentation'],
                    'h5pLib' => 'H5P.CoursePresentation 1.27',
                    'demo_activity_id' => '0',
                    'demo_video_id' => '',
                    'type' => 'h5p',
                    'created_at' => $currentDate,
                    'deleted_at' => null,
                    'organization_id' => $organizationId,
                ]);
            }
        }
    }

